def transform(grid):
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    objects = Counter()

    for row in grid:
        active = None
        for value in row + [background]:
            if value != active:
                if active is not None and active != background:
                    objects[active] += 1
                active = value

    colors = sorted(objects, key=lambda c: (-objects[c], c))
    # The bars represent objects; list the color-3 bars before color-2 bars.
    colors.sort(key=lambda c: (0 if c == 3 else 1, c))
    cells = []
    for color in colors:
        cells.extend([color] * objects[color])
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
